import { beforeEach, describe, expect, it, vi } from "vitest";
import { randomUUID } from "node:crypto";

const mocks = vi.hoisted(() => ({
  handlers: new Map<string, (context: unknown) => Promise<unknown>>(),
  users: vi.fn(),
  account: vi.fn(),
  deleteAccount: vi.fn(),
  cleanup: vi.fn(),
  pendingCleanup: vi.fn(),
  reconcile: vi.fn(),
  dispatch: vi.fn(),
  publish: vi.fn(),
}));
vi.mock("inngest", async (original) => ({
  ...(await original<typeof import("inngest")>()),
  Inngest: class {
    send = mocks.publish;
    createFunction(
      opts: { id: string; triggers: unknown },
      handler: (context: unknown) => Promise<unknown>,
    ) {
      mocks.handlers.set(opts.id, handler);
      return { opts };
    }
  },
}));
vi.mock("@/lib/db", () => ({
  db: {
    user: {
      findMany: mocks.users,
      findUnique: mocks.account,
    },
  },
}));
vi.mock("@/lib/gmail", () => ({}));
vi.mock("@/lib/storage", () => ({
  cleanupAttachments: mocks.cleanup,
  hasPendingAttachmentCleanup: mocks.pendingCleanup,
}));
vi.mock("@/lib/account", () => ({
  cleanupDeletedAccount: mocks.deleteAccount,
  DELETION_DRAIN_MS: 15 * 60000,
  DELETION_RETENTION_MS: 30 * 24 * 60 * 60 * 1000,
}));
vi.mock("@/lib/usage-reconciliation", () => ({
  reconcileUsagePage: mocks.reconcile,
  dispatchUsagePending: mocks.dispatch,
}));
import {
  accountMaintenance,
  checkReplies,
  maintenance,
  quotaReconciliation,
} from "@/lib/inngest";

const userId = "f5a05555-5732-4463-b29e-d4cdfef33354";
const run = async (_id: string, work: () => unknown) => work();

describe("background schedules", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    mocks.pendingCleanup.mockResolvedValue(false);
  });

  it("removes both reply jobs and disables direct legacy calls", async () => {
    expect(mocks.handlers.has("scheduled-replies")).toBe(false);
    expect(mocks.handlers.has("refresh-replies")).toBe(false);
    expect(await checkReplies(userId, true)).toEqual({
      checked: 0,
      replies: 0,
      disabled: true,
    });
    expect(mocks.dispatch).not.toHaveBeenCalled();
    expect(mocks.publish).not.toHaveBeenCalled();
  });

  it("keeps daily attachment cleanup and leaves deletion to its own daily job", () => {
    expect([...mocks.handlers.keys()].sort()).toEqual([
      "account-maintenance",
      "maintenance",
      "quota-reconciliation",
      "send-individual-email",
    ]);
    expect(quotaReconciliation.opts).toMatchObject({
      triggers: { cron: "0 * * * *" },
      concurrency: 1,
    });
    expect(maintenance.opts).toMatchObject({
      triggers: { cron: "0 3 * * *" },
      concurrency: 1,
    });
  });

  it("runs idle recovery in one step without publishing events", async () => {
    mocks.reconcile.mockResolvedValue({ processed: 100, failed: 0 });
    const stepRun = vi.fn(run);
    expect(
      await mocks.handlers.get("quota-reconciliation")!({
        step: { run: stepRun },
      }),
    ).toEqual({ processed: 100, failed: 0 });
    expect(stepRun).toHaveBeenCalledExactlyOnceWith(
      "reconcile-owners-0",
      expect.any(Function),
    );
    expect(mocks.publish).not.toHaveBeenCalled();
  });

  it("delegates recovery publication to the existing reconciler", async () => {
    const events = [
      { name: "mailloop/email.queued", data: { userId, sendId: randomUUID() } },
    ];
    mocks.reconcile.mockImplementation(async (publish) => {
      await publish(events);
      return { processed: 1, failed: 0 };
    });
    const stepRun = vi.fn(run);
    expect(
      await mocks.handlers.get("quota-reconciliation")!({
        step: { run: stepRun },
      }),
    ).toEqual({ processed: 1, failed: 0 });
    expect(stepRun).toHaveBeenCalledExactlyOnceWith(
      "reconcile-owners-0",
      expect.any(Function),
    );
    expect(mocks.publish).toHaveBeenCalledWith(events);
  });

  it("uses only one discovery step for more than 100 idle accounts and emits no cleanup events", async () => {
    const users = Array.from({ length: 101 }, () => ({
      id: randomUUID(),
      currentAttachmentId: null,
      deletionRequestedAt: null,
    })).sort((a, b) => a.id.localeCompare(b.id));
    mocks.users
      .mockResolvedValueOnce(users.slice(0, 100))
      .mockResolvedValueOnce(users.slice(100))
      .mockResolvedValueOnce([]);
    const stepRun = vi.fn(run),
      sendEvent = vi.fn();
    await mocks.handlers.get("maintenance")!({
      step: { run: stepRun, sendEvent },
    });
    expect(stepRun).toHaveBeenCalledExactlyOnceWith(
      "discover-cleanup",
      expect.any(Function),
    );
    expect(mocks.users).toHaveBeenNthCalledWith(
      2,
      expect.objectContaining({
        where: { id: { gt: users[99].id } },
      }),
    );
    expect(mocks.pendingCleanup).toHaveBeenCalledTimes(101);
    expect(sendEvent).not.toHaveBeenCalled();
    expect(mocks.dispatch).not.toHaveBeenCalled();
    expect(mocks.reconcile).not.toHaveBeenCalled();
  });

  it("schedules only accounts with pending cleanup without running providers inline", async () => {
    const healthy = "f5a05555-5732-4463-b29e-d4cdfef33355";
    mocks.users
      .mockResolvedValueOnce([
        {
          id: userId,
          deletionRequestedAt: new Date("2000-01-01"),
          currentAttachmentId: null,
        },
        { id: healthy, deletionRequestedAt: null, currentAttachmentId: null },
      ])
      .mockResolvedValueOnce([]);
    mocks.pendingCleanup.mockResolvedValue(true);
    const sendEvent = vi.fn();
    await mocks.handlers.get("maintenance")!({ step: { run, sendEvent } });
    expect(mocks.users).toHaveBeenNthCalledWith(
      2,
      expect.objectContaining({ where: { id: { gt: healthy } } }),
    );
    expect(mocks.deleteAccount).not.toHaveBeenCalled();
    expect(mocks.cleanup).not.toHaveBeenCalled();
    expect(mocks.pendingCleanup).toHaveBeenCalledExactlyOnceWith(healthy, null);
    expect(mocks.dispatch).not.toHaveBeenCalled();
    expect(sendEvent).toHaveBeenCalledWith("cleanup-0", [
      { name: "mailloop/account.maintenance", data: { userId: healthy } },
    ]);
  });

  it("publishes eligible account IDs in batches of 100 after discovery completes", async () => {
    const users = Array.from({ length: 205 }, () => ({
      id: randomUUID(),
      deletionRequestedAt: null,
      currentAttachmentId: null,
    })).sort((a, b) => a.id.localeCompare(b.id));
    mocks.users
      .mockResolvedValueOnce(users.slice(0, 100))
      .mockResolvedValueOnce(users.slice(100, 200))
      .mockResolvedValueOnce(users.slice(200))
      .mockResolvedValueOnce([]);
    mocks.pendingCleanup.mockResolvedValue(true);
    const stepRun = vi.fn(run),
      sendEvent = vi.fn();
    await mocks.handlers.get("maintenance")!({
      step: { run: stepRun, sendEvent },
    });
    expect(stepRun).toHaveBeenCalledOnce();
    expect(sendEvent.mock.calls.map(([, events]) => events.length)).toEqual([
      100, 100, 5,
    ]);
    expect(sendEvent.mock.calls.map(([id]) => id)).toEqual([
      "cleanup-0",
      "cleanup-1",
      "cleanup-2",
    ]);
    expect(sendEvent.mock.calls.flatMap(([, events]) => events)).toEqual(
      users.map(({ id }) => ({
        name: "mailloop/account.maintenance",
        data: { userId: id },
      })),
    );
    expect(mocks.pendingCleanup).toHaveBeenCalledTimes(205);
  });
  it("ignores stale deletion events and cleans attachments for active accounts", async () => {
    const healthy = "f5a05555-5732-4463-b29e-d4cdfef33355";
    expect(accountMaintenance.opts).toMatchObject({
      concurrency: { limit: 1, key: "event.data.userId" },
    });
    mocks.account
      .mockResolvedValueOnce({ deletionRequestedAt: new Date() })
      .mockResolvedValueOnce({ deletionRequestedAt: null });
    await mocks.handlers.get("account-maintenance")!({
      event: { data: { userId } },
      step: { run },
    });
    await mocks.handlers.get("account-maintenance")!({
      event: { data: { userId: healthy } },
      step: { run },
    });
    expect(mocks.deleteAccount).not.toHaveBeenCalled();
    expect(mocks.cleanup).toHaveBeenCalledWith(healthy);
  });
  it("ignores missing accounts and validates cleanup tenant IDs", async () => {
    mocks.account.mockResolvedValue(null);
    await mocks.handlers.get("account-maintenance")!({
      event: { data: { userId } },
      step: { run },
    });
    await expect(
      mocks.handlers.get("account-maintenance")!({
        event: { data: { userId: "../../other-tenant" } },
        step: { run },
      }),
    ).rejects.toThrow();
    expect(mocks.account).toHaveBeenCalledOnce();
    expect(mocks.cleanup).not.toHaveBeenCalled();
    expect(mocks.deleteAccount).not.toHaveBeenCalled();
  });
});
